inputs.expression:
(
  /* Get applications from HTTP response */
  $apps := actions.Fetch_Applications.result.body;

  /* Get the target acronym from inputs */
  $target_acronym := inputs.app_acronym;

  /* Find the application matching the acronym */
  $result := $apps[acronym = $target_acronym][0];

  /* Return the matched application */
  $result
)
